pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, uint8 numPlays, uint8 winThreshold) public {
        // Bound number of plays to a reasonable range for gas
        numPlays = uint8(bound(numPlays, 1, 20));
        // winThreshold determines the random outcome: if (seed % (i+1)) % 2 == 0, the player wins
        // To ensure variability, we use bounded seed
        seed = bound(seed, 0, type(uint256).max);

        address player = address(0x1234);
        uint256 expectedPot = 0;
        uint256 expectedBalance = 0;
        uint256 feeAmount = 1;
        uint256 ticketAmount = 10;

        for (uint8 i = 0; i < numPlays; i++) {
            // Compute win condition deterministically from seed and play index
            bool isWin = ((seed % (uint256(i) + 1)) % 2) == 0;

            vm.deal(player, ticketAmount);
            vm.prank(player);
            if (isWin && expectedPot > 0) {
                // Before the play, if it's a win and pot > 0, pot is added to, then transferred, and reset to 0
                // But we need to simulate the correct behavior for reference.
                // For the invariant, we will compute what pot and balance SHOULD be after each play assuming correct logic.
                // In the reference, if win: pot = 0; balance decreases by (old pot + ticketAmount) and bank gets fee, player gets rest.
                // We'll just track cumulative fees paid to bank, because the invariant is:
                // address(c).balance == c.pot() + totalFeesPaid
                // This holds for reference because pot is reset, but fails for mutant because pot accumulates past balance.
            }
        }

        // Actually simulate the sequence and record outcomes
        uint256 totalFeesPaid = 0;
        uint256 potBefore;
        for (uint8 i = 0; i < numPlays; i++) {
            bool isWin = ((seed % (uint256(i) + 1)) % 2) == 0;
            potBefore = c.pot();

            vm.deal(player, ticketAmount);
            vm.prank(player);
            c.play{value: ticketAmount}();

            if (isWin && potBefore > 0) {
                // In reference, pot becomes 0, bank gets fee, player gets potBefore + ticketAmount - fee
                totalFeesPaid += feeAmount;
                // In mutant, pot remains unchanged (potBefore + ticketAmount), and player gets that - fee
                // But transfer fails if contract doesn't have enough balance. That's fine, we can catch revert.
            }
        }

        // After all calls, the invariant: contract balance == pot + totalFeesPaid
        // This must hold for reference for ANY sequence, but fails for mutant when there is a win.
        // We assert that this equality holds.
        assertEq(address(c).balance, c.pot() + totalFeesPaid, "Invariant violated: balance != pot + fees");
    }
}

