pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // Admissible domain: we will simulate a variable number of plays triggered by the fuzzer
        uint256 plays = bound(seed, 1, 10);
        uint256 totalSent = 0;
        uint256 totalFeeToBank = 0;

        address bank = c.bank();
        uint256 initialBankBalance = bank.balance;

        for (uint256 i = 0; i < plays; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 10 ether + 1 ether); // plenty for ticket and gas
            vm.prank(player);

            // try/catch to handle reverts and wins/losses
            bool won;
            uint256 potBefore = c.pot();
            uint256 bankBefore = bank.balance;
            uint256 playerBefore = player.balance;

            try c.play{value: 10}() {
                won = true;
            } catch {
                won = false;
            }

            if (!won) {
                // play reverted: no state change expected
                assertEq(c.pot(), potBefore);
                continue;
            }

            totalSent += 10;

            // After play succeeds, the invariant must hold:
            // pot == (totalSent - totalFeeToBank) % (some relation)
            // The exact random outcome is fuzzed, but we can assert:
            // If pot is non-zero, no payout happened; if pot is zero, a payout happened
            uint256 potAfter = c.pot();
            uint256 bankAfter = bank.balance;
            uint256 playerAfter = player.balance;

            // Bank's balance must have increased by at most 1 (fee) if pot reset to 0, or 0 otherwise
            // Payout logic: if random == 0, bank gets 1, winner gets pot-1, pot=0.
            // If random == 1, nothing happens, pot stays.
            // Invariant: bank.balance increase == 1 if pot became 0, else 0.
            if (potAfter == 0) {
                // win
                assertEq(bankAfter - bankBefore, 1, "bank fee on win");
                // winner gets previous pot + 10 - 1 - previous pot? Wait: potBefore included previous? No.
                // Actually pot = current pot before this call.
                // In correct C: potBefore = cumulative msg.values - fees paid out so far.
                // On win: bank gets 1, winner gets (potBefore + 10) - 1 = potBefore + 9, pot=0.
                uint256 expectedWinnings = potBefore + 10 - 1;
                assertEq(playerAfter - playerBefore, expectedWinnings, "winnings");
                totalFeeToBank += 1;
            } else {
                // loss: pot increased by exactly 10 (or 1 in mutant).
                // Bank balance unchanged
                assertEq(bankAfter, bankBefore, "bank unchanged on loss");
                // Player lost exactly 10
                assertEq(playerBefore - playerAfter, 10, "player loses ticket");
                // For correct C: potAfter == potBefore + 10
                // For mutant: potAfter == potBefore + 1
                // The assertion that distinguishes: potAfter == potBefore + 10 OR != ?
                // We need a single assertion true for all inputs on correct, false on mutant.
                // The simplest invariant: pot = total msg.value received - total fees paid out.
                // total msg.value received = totalSent.
                // total fees paid out = number of wins * 1.
                // We can track number of wins and check.
                uint256 totalWins = totalFeeToBank; // equals wins so far
                uint256 expectedPot = totalSent - totalWins;
                // This invariant holds for correct contract at all times after each play.
                // For mutant, pot increments by 1 per call instead of 10, so after first loss, expectedPot=10, actual pot=1. Fails.
                assertEq(potAfter, expectedPot, "pot invariant");
            }
        }
    }
}

