pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 run) public {
        // Bound the number of play() calls to avoid excessive loops yet allow the fuzzer to explore sequences.
        run = bound(run, 0, 10);
        // Track the total value sent to the contract via play().
        uint256 totalSent = 0;
        for (uint256 i = 0; i < run; i++) {
            address actor = address(uint160(uint256(keccak256(abi.encode(i, run)))));
            vm.deal(actor, 10);
            vm.prank(actor);
            // Low-level call to capture success without reverting the test on require failures
            (bool ok, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
            if (ok) {
                totalSent += 10;
            }
        }
        // Assert invariant: the contract's Ether balance should equal totalSent + the initial constructor endowment (0 in this case),
        // BUT the reference property uses pot directly: pot must equal the total value sent before any payout.
        // Since a win resets pot to 0 and transfers FEE_AMOUNT to bank + remainder to winner,
        // we check a property about pot that holds regardless of win/loss history.
        // Correct contract: pot = totalSent % 10 after each call? Actually, any call either adds 10 to pot (loss)
        // or resets pot to 0 and pays out (win). The invariant pot <= totalSent always holds, and exact equality
        // before a win payout. A robust invariant: pot % 10 == totalSent % 10.
        // Mutant: pot = number_of_calls, so pot % 10 != totalSent % 10 when totalSent != run*10.
        assertTrue(c.pot() % 10 == totalSent % 10);
    }
}

