    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Admissible domain: seed is any uint256, we'll use it to control the random outcome via block.timestamp and block.difficulty
        vm.assume(seed < type(uint64).max);
        uint64 ts = uint64(seed);
        uint64 diff = uint64(seed + 1);
        vm.warp(ts);
        vm.roll(block.number); // to make block.difficulty set-able, but we can't set difficulty directly, so we rely on timestamp only
        // Since we can't directly set block.difficulty, we just use seed to warp timestamp and hope the fuzzer finds a losing combination;
        // but the property must hold for all inputs, including losing ones, so we need to ensure we cover both outcomes.
        // We actually don't need to force a win; the property must hold universally. The reference holds for both win and loss.
        // The mutant only differs on a win, so the property must still hold for the reference on a loss and the mutant as well on loss,
        // but the mutant will fail the assertion on a win. So the fuzzer just needs to explore both outcomes.
        uint256 botAmt = 10;
        vm.deal(address(this), botAmt);
        c.play{value: botAmt}();
        // After any single play, the following invariant holds for C:
        // If pot == 0 (meaning a win just happened), then address(c).balance must equal address(c.bank()).balance
        // because the fee was sent to bank and the rest to the player, leaving contract with 0.
        // On a loss, pot > 0 and address(c).balance is whatever, but the invariant still holds vacuously if pot > 0.
        // However, after a win, the mutant leaves contract balance > 0 because it didn't deduct fee from pot, but pot becomes 0,
        // so address(c).balance would be > address(c.bank()).balance, violating the rule.
        // This rule holds for C for all outcomes.
        bool potZero = (c.pot() == 0);
        if (potZero) {
            assertEq(address(c).balance, address(c.bank()).balance);
        } else {
            // Not a win, nothing to check; we can just assert true or skip, but we need a single assertion.
            // We can assert that the invariant holds: if pot == 0, balances match.
            // To make it a single assertTrue, we can assert that if pot == 0 then balances equal.
            // assertTrue(!potZero || address(c).balance == address(c.bank()).balance);
            // But we'll just assert that the implication holds.
            assertTrue(!potZero || address(c).balance == address(c.bank()).balance);
        }
    }
}

