        vm.warp(seed % 1000 + 1);
        // Play once
        vm.prank(player);
        c.play{value: 10}();
        // After the call, if pot is 0 a win occurred. In the reference, the fee (1 wei)
        // is sent to the bank, so the contract balance must be exactly FEE_AMOUNT (1 wei).
        // The buggy version sends the full pot to the player, draining the contract to 0.
        assertTrue(c.pot() != 0 || address(c).balance == 1);
    }
}

