pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 runs) public {
        // Ensure at least one play, and bound to a reasonable number of iterations
        runs = bound(runs, 1, 20);
        address player = address(0x44e97af4418b7a17aabd8090bea0a471a366305c);
        vm.deal(player, runs * 10 ether);
        vm.startPrank(player);

        bool won = false;
        for (uint256 i = 0; i < runs; i++) {
            // Re-roll the blockchain state to get a different random outcome each time
            vm.roll(block.number + 1);
            vm.warp(block.timestamp + 1);
            try c.play{value: 10}() {
                // If play did not revert, random must have been 0 (win)
                won = true;
            } catch {
                // If play reverted, random was 1 (loss), pot remains non-zero, continue
            }
            // If we already got a win, we can stop because further plays may change the balance
            if (won) break;
        }
        vm.stopPrank();

        // If no win occurred, the invariant trivially holds (balance can be anything);
        // we only assert when a win happened.
        vm.assume(won);

        // After a single winning play, the contract should hold exactly the FEE_AMOUNT (1 wei)
        // because the bank received 1 wei and the pot was reset to 0.
        // The buggy version transfers the full pot to the player without deducting the fee,
        // leaving the contract with 0 balance.
        assertEq(address(c).balance, 1);
    }
}

