pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player, uint256 seed) public {
        vm.assume(player != address(0) && player != address(c));
        // player must send exactly TICKET_AMOUNT; seed determines the random outcome
        uint256 ticket = 10;
        vm.deal(player, ticket);
        // Use seed to influence block.difficulty indirectly; we warp block.timestamp and set block.prevrandao to alter the random result
        vm.warp(seed % 1_000_000);
        vm.roll(uint256(keccak256(abi.encode(seed))) % 1_000_000);
        vm.prank(player);
        // Try to trigger a winning play (random == 0) by using a fresh block's prevrandao
        c.play{value: ticket}();
        // After the call, if pot is 0 (a win occurred), the contract's balance must equal FEE_AMOUNT (1 wei)
        // In the buggy version, the entire pot including the fee is sent to the player, leaving balance 0
        assertTrue(c.pot() != 0 || address(c).balance == 1);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 value) public payable {
        require(value == 1 || value == 10);
        uint256 potBefore = c.pot();
        c.play{value: value}();
        uint256 potAfter = c.pot();
        assert(potAfter == potBefore + value);
    }
}

